package com.cpf.starter.tcp;import java.time.*;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;class CpfTcpCorrelationRegistryTest {@Test void completesOutOfOrderAndCapturesOrphan(){var c=new CpfTcpCorrelationRegistry(2,2);var clock=Clock.fixed(Instant.EPOCH,ZoneOffset.UTC);var a=c.register("a",Duration.ofSeconds(1),clock);var b=c.register("b",Duration.ofSeconds(1),clock);c.complete("b",new byte[]{2},clock);c.complete("a",new byte[]{1},clock);assertThat(a.join()).containsExactly(1);assertThat(b.join()).containsExactly(2);assertThat(c.complete("orphan",new byte[]{9},clock)).isFalse();assertThat(c.orphans()).hasSize(1);}}
